use moloch_live_runtime::feedback;
#[path="../src/package_feedback.rs"] mod package_feedback;
use baal_transport_service::{Scope,Permit,Receipt,TransportError,multi_leg::{self,Basket,Leg,Side,ResponseEvidence,ZeroExecutionReason}};
use moloch_replay::session::Session;
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
const T:&str="11111111-1111-4111-8111-111111111111";
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_022_400_000+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash<T:serde::Serialize>(v:&T)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn book(ex:&str)->Value{json!({"type":"book","receivedAt":iso(0),"book":{"tournamentId":T,"marketId":ex,"exchangeId":ex,"sequence":"1","sourceAt":iso(0),"requestStartedAt":iso(0),"receivedAt":iso(0),"bids":[{"price":"0.400000","quantity":20}],"asks":[{"price":"0.450000","quantity":20}]}})}
struct Fixture{bank:Session,root:std::path::PathBuf,scope:Scope,basket:Basket,permit:Permit,n:u64}
impl Fixture{
 fn new()->Self{
  let root=std::env::temp_dir().join(format!("package-feedback-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));
  let policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"10.000000","quantity":15,"maximumMarkets":3,"minimumSpreadTicks":1000,"entryStopAt":iso(100000)});
  let seed=json!({"runId":"run-1","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});
  let mut bank=Session::open_live(&root,&policy,&seed).unwrap();for(i,ex)in ["101","102"].into_iter().enumerate(){bank.accept("books",i as u64+1,&book(ex)).unwrap();}
  let scope=Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into()),("102".into(),"102".into())].into()};
  let basket=Basket{idempotency_key:"run-package-1".into(),tournament_id:T.into(),maximum_cost:"5.250000".into(),relationship_constraint:None,legs:vec![Leg{exchange_id:"101".into(),side:Side::No,quantity:5,limit_price:"0.600000".into()},Leg{exchange_id:"102".into(),side:Side::Yes,quantity:5,limit_price:"0.450000".into()}]};
  let permit=Permit{run_id:"run-1".into(),intent_id:"package-1".into(),owner:"Codex".into(),expires_at_ms:(1_792_022_400_000u64+9000),maximum_quantity:10,maximum_cost:"5.250000".into()};
  let reserve=json!({"type":"live_package_reserve","source":"moloch_live_dispatcher","receivedAt":iso(1),"processedAt":iso(1),"packageId":"package-1","proofHash":"a".repeat(64),"bankScope":{"runId":"run-1","bankManifestHash":bank.manifest_hash(),"tournamentId":T},"expiresAt":iso(9000),"economics":{"maximumCost":"5.250000","minimumPayout":"6.000000","minimumSurplus":"0.750000","feeTotal":"0.000000"},"legs":[{"marketId":"101","exchangeId":"101","side":"NO","quantity":5,"limitPrice":"0.600000","bookHash":hash(&book("101")["book"])},{"marketId":"102","exchangeId":"102","side":"YES","quantity":5,"limitPrice":"0.450000","bookHash":hash(&book("102")["book"])}]});
  bank.accept("dispatch",1,&reserve).unwrap();let mut attempt=reserve.clone();attempt["type"]=json!("live_package_attempt");attempt["receivedAt"]=json!(iso(3001));attempt["processedAt"]=json!(iso(3001));attempt["requestHash"]=json!(hash(&multi_leg::request_spec(&basket,&scope,&permit).unwrap()));attempt["idempotencyKey"]=json!(&basket.idempotency_key);attempt["bookHashes"]=json!({"101":hash(&book("101")["book"]),"102":hash(&book("102")["book"])});bank.accept("dispatch",2,&attempt).unwrap();Self{bank,root,scope,basket,permit,n:2}
 }
 fn p(&self)->Value{self.bank.engine().package_records()[0].clone()}
 fn accept(&mut self,e:&Value){self.n+=1;self.bank.accept("dispatch",self.n,e).unwrap();}
 fn ack(&self)->Receipt{Receipt{endpoint:"/orders/multi-leg".into(),status:200,request_started_at:iso(3010),received_at:iso(3100),data:json!({"results":[{"index":0,"data":{"orderId":"901","exchangeId":"101","side":"no","action":"buy","quantity":5,"quantityTraded":-5,"remainingQuantity":0,"price":0.6,"fillPrice":0.6,"totalCost":3,"open":false,"all":null,"terminalReasonCode":null}},{"index":1,"data":{"orderId":"902","exchangeId":"102","side":"yes","action":"buy","quantity":5,"quantityTraded":5,"remainingQuantity":0,"price":0.45,"fillPrice":0.45,"totalCost":2.25,"open":false,"all":null,"terminalReasonCode":null}}]})}}
 fn event_ack(&self,r:&Receipt)->feedback::Result<Value>{package_feedback::acknowledgment(&self.bank,&self.p(),&self.basket,&self.scope,&self.permit,r,&iso(3101))}
 fn zero(&self)->(ResponseEvidence,TransportError){let spec=multi_leg::request_spec(&self.basket,&self.scope,&self.permit).unwrap();let data=json!({"error":{"code":"RATE_LIMITED","message":"sanitized"}});let bytes=serde_json::to_vec_pretty(&data).unwrap();let e=ResponseEvidence{private_body_path:self.root.join("original.body"),private_metadata_path:self.root.join("original.metadata"),body_sha256:format!("{:x}",Sha256::digest(&bytes)),request_sha256:hash(&spec),status:429,request_started_at:iso(3010),received_at:iso(3100),complete_body:true};std::fs::write(&e.private_body_path,bytes).unwrap();std::fs::write(&e.private_metadata_path,serde_json::to_vec(&json!({"evidence":e,"request":spec})).unwrap()).unwrap();(e,TransportError{code:"HTTP_ERROR".into(),status:Some(429),may_have_executed:false,retry_after_ms:1000,order_id:None,api_code:Some("RATE_LIMITED".into())})}
}
// Temporary private fixtures are removed after Session has released its lock.
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.root);}}
#[test]fn full_response_ack_is_atomic_source_bound_and_creates_no_fills(){let mut f=Fixture::new();let r=f.ack();let event=f.event_ack(&r).unwrap();assert_eq!(event["acknowledgments"][0]["receiptHash"],feedback::digest(&r).unwrap());assert_eq!(event["acknowledgments"][1]["receiptHash"],feedback::digest(&r).unwrap());f.accept(&event);assert_eq!(f.bank.engine().live_order_bindings().len(),2);assert!(f.bank.engine().fills().is_empty());assert_eq!(f.bank.engine().report().unwrap()["ownedCost"],"0.000000");assert!(package_feedback::complete(&f.bank,&f.p(),&f.scope,&iso(3200)).is_err());}
#[test]fn partial_resting_wrong_endpoint_clock_or_scope_ack_denies_without_mapping(){let f=Fixture::new();for case in ["partial","resting","endpoint","clock","malformed"]{let mut r=f.ack();match case{"partial"=>r.data["results"][1]["data"]["quantityTraded"]=json!(4),"resting"=>r.data["results"][1]["data"]["open"]=json!(true),"endpoint"=>r.endpoint="/orders".into(),"clock"=>r.request_started_at=iso(3200),_=>r.data["results"][1]["data"]["all"]=json!({})};assert!(f.event_ack(&r).is_err(),"{case}");}let mut p=f.p();p["bankScope"]["runId"]=json!("other");assert!(package_feedback::acknowledgment(&f.bank,&p,&f.basket,&f.scope,&f.permit,&f.ack(),&iso(3200)).is_err());assert!(f.bank.engine().live_order_bindings().is_empty());}
#[test]fn original_zero_response_binds_raw_metadata_request_and_canonical_hash(){let mut f=Fixture::new();let(e,error)=f.zero();let z=package_feedback::no_execution(&f.bank,&f.p(),&f.basket,&f.scope,&f.permit,&error,&ZeroExecutionReason::RateLimited,&e,&iso(3101)).unwrap();assert_ne!(z["evidence"]["responseHash"],e.body_sha256);f.accept(&z);assert_eq!(f.p()["phase"],"no_execution");assert!(f.bank.engine().fills().is_empty());}
#[test]fn altered_zero_evidence_never_releases_reservations(){let f=Fixture::new();let(e,mut error)=f.zero();error.may_have_executed=true;assert!(package_feedback::no_execution(&f.bank,&f.p(),&f.basket,&f.scope,&f.permit,&error,&ZeroExecutionReason::RateLimited,&e,&iso(3101)).is_err());error.may_have_executed=false;std::fs::write(&e.private_metadata_path,b"{}").unwrap();assert!(package_feedback::no_execution(&f.bank,&f.p(),&f.basket,&f.scope,&f.permit,&error,&ZeroExecutionReason::RateLimited,&e,&iso(3101)).is_err());let(e,error)=f.zero();std::fs::write(&e.private_body_path,b"{}").unwrap();assert!(package_feedback::no_execution(&f.bank,&f.p(),&f.basket,&f.scope,&f.permit,&error,&ZeroExecutionReason::RateLimited,&e,&iso(3101)).is_err());assert_eq!(f.p()["phase"],"attempted");}
#[test]fn genuine_signed_component_tapes_and_expiry_free_terminals_complete_only_after_admission(){let mut f=Fixture::new();let ack=f.event_ack(&f.ack()).unwrap();f.accept(&ack);for i in 0..2 {let actual=if i==0{"901"}else{"902"};let ex=if i==0{"101"}else{"102"};let side=if i==0{"no"}else{"yes"};let price=if i==0{0.6}else{0.45};let signed=if i==0{-5}else{5};let order=Receipt{endpoint:format!("/orders/{actual}"),status:200,request_started_at:iso(4000+i as i64*1000),received_at:iso(4100+i as i64*1000),data:json!({"id":actual,"exchangeId":ex,"tournamentId":T,"side":side,"action":"buy","priceLimit":price,"quantity":5,"quantityFilled":5,"open":false})};let tape=Receipt{endpoint:format!("/orders/{actual}/fills?limit=200&tournamentId={T}"),status:200,request_started_at:iso(4200+i as i64*1000),received_at:iso(4300+i as i64*1000),data:json!({"orderId":actual,"exchangeId":ex,"tournamentId":T,"totalQuantityFilled":signed,"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null},"data":[{"id":format!("80{i}"),"quantity":signed,"side":side,"price":price,"filledAt":iso(3020+i as i64)}]})};let mut wrong=tape.clone();wrong.endpoint="/portfolio/fills".into();assert!(package_feedback::fills(&f.bank,&f.p(),&f.scope,i,&wrong,&iso(4400+i as i64*1000)).is_err());let fills=package_feedback::fills(&f.bank,&f.p(),&f.scope,i,&tape,&iso(4400+i as i64*1000)).unwrap();for event in fills{f.accept(&event);}assert!(package_feedback::complete(&f.bank,&f.p(),&f.scope,&iso(4401+i as i64*1000)).is_err());let terminal=package_feedback::terminal(&f.bank,&f.p(),&f.scope,i,&order,&tape,&iso(4500+i as i64*1000)).unwrap().unwrap();assert!(order.data.get("expirationDate").is_none());f.accept(&terminal);}let event=package_feedback::complete(&f.bank,&f.p(),&f.scope,&iso(5600)).unwrap();f.accept(&event);assert_eq!(f.p()["phase"],"complete");assert_eq!(f.bank.engine().report().unwrap()["ownedCost"],"5.250000");assert_eq!(f.bank.engine().fills().len(),2);}
